    check: { out: '4', tests: [['find_index(s, 7)', 3, 'vector<int> s = {1, 3, 5, 7, 9};'], ['find_index(s, 1)', 0, 'vector<int> s = {1, 3, 5, 7, 9};'], ['find_index(s, 4)', -1, 'vector<int> s = {1, 3, 5, 7, 9};'], ['find_index(s, 1)', -1, 'vector<int> s;']] },
    hint: 'while (lo <= hi) { int mid = (lo + hi) / 2; if (v[mid] == target) return mid; if (v[mid] < target) lo = mid + 1; else hi = mid - 1; }',
    solution: R`#include <iostream>
#include <vector>
using namespace std;

int find_index(vector<int> v, int target) {
    int lo = 0, hi = v.size() - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (v[mid] == target) {
            return mid;
        } else if (v[mid] < target) {
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    vector<int> sorted = {1, 3, 5, 7, 9};
    cout << find_index(sorted, 9) << endl;
    return 0;
}`,
