  const BASE_CSS = 'body {\n  margin: 0;\n  font-family: system-ui, sans-serif;\n  background: #0b1020;\n  color: #e8ecff;\n}\n.hero {\n  min-height: 100vh;\n  display: grid;\n  place-content: center;\n  text-align: center;\n  gap: 8px;\n  padding: 24px;\n}\nh1 { font-size: 2.4rem; margin: 0; }\n';
