  const q = (code, options, answer, why) => ({ code, options, answer, why });
  const h1Text = (f) => { const m = /<h1[^>]*>([\s\S]*?)<\/h1>/i.exec(f['index.html']); return m ? m[1].replace(/<[^>]+>/g, '').trim() : ''; };

  // lesson 1
  const L1s = F(html('My First Deploy', HERO), BASE_CSS, '// Runs in the browser after the page loads.\ndocument.title = "My site · " + new Date().getFullYear();\n');
  // lesson 2: three bugs
  const L2s = F(html('Lint Lab', '  <main class="hero">\n    <div class="card">\n      <h1>Lint Lab</h1>\n      <p>Three bugs are hiding in this project.</p>\n  </main>'), BASE_CSS + '.card {\n  padding 16px;\n  border-radius: 12px;\n}\n', 'function greet(name) {\n  console.log("Hi " + name;\n}\ngreet("Ada");\n');
  const L2f = F(html('Lint Lab', '  <main class="hero">\n    <div class="card">\n      <h1>Lint Lab</h1>\n      <p>Three bugs are hiding in this project.</p>\n    </div>\n  </main>'), BASE_CSS + '.card {\n  padding: 16px;\n  border-radius: 12px;\n}\n', 'function greet(name) {\n  console.log("Hi " + name);\n}\ngreet("Ada");\n');
  // lesson 3
  const L3f = F(html('Hello Cloud', HERO.replace('Hello, World', 'Hello from the cloud!')), BASE_CSS, L1s['app.js']);
  // lesson 4: styling a card
  const L4s = F(html('Styled Card', '  <main class="hero">\n    <h1>Meet the card</h1>\n    <p>Give me a class and some style.</p>\n  </main>'), BASE_CSS, '');
  const L4f = F(html('Styled Card', '  <main class="hero">\n    <h1>Meet the card</h1>\n    <p class="card">Give me a class and some style.</p>\n  </main>'), BASE_CSS + '.card {\n  padding: 18px 22px;\n  border-radius: 14px;\n  background: #1a2548;\n  border: 1px solid #3a4a8a;\n}\n', '');
  // lesson 5: interactivity
  const L5s = F(html('Click Counter', '  <main class="hero">\n    <h1>Clicks: <span id="n">0</span></h1>\n    <button id="btn">Click me</button>\n  </main>'), BASE_CSS + 'button { font: inherit; padding: 10px 18px; border-radius: 10px; border: 0; background: #6a8bff; color: #fff; cursor: pointer; }\n', '// TODO: count the clicks on #btn and show them in #n\n');
  const L5f = F(L5s['index.html'], L5s['style.css'], 'let clicks = 0;\nconst out = document.getElementById("n");\ndocument.getElementById("btn").addEventListener("click", () => {\n  clicks += 1;\n  out.textContent = clicks;\n});\n');
  // lesson 6: secrets
  const L6s = F(html('Config', '  <main class="hero">\n    <h1>Environment: <span id="env"></span></h1>\n  </main>'), BASE_CSS, 'const API_KEY = "sk_live_51H8xK2LmN0pQrStUv";\nconst CONFIG = { env: "development" };\ndocument.getElementById("env").textContent = CONFIG.env;\n');
  const L6f = F(L6s['index.html'], BASE_CSS, '// Secrets live in the host\'s environment variables, never in the repo.\nconst CONFIG = { env: "production" };\ndocument.getElementById("env").textContent = CONFIG.env;\n');
  // lesson 7: capstone todo app
  const TODO_CSS = BASE_CSS + 'ul { list-style: none; padding: 0; margin: 12px 0 0; }\nli { padding: 8px 12px; margin: 6px 0; border-radius: 8px; background: #1a2548; }\ninput, button { font: inherit; padding: 10px 12px; border-radius: 10px; border: 0; }\nbutton { background: #6a8bff; color: #fff; cursor: pointer; }\n';
  const L7s = F(html('Todo Capstone', '  <main class="hero">\n    <h1>My Todo List</h1>\n    <div>\n      <input id="todo" placeholder="What needs doing?">\n      <button id="add">Add</button>\n    </div>\n    <ul id="list"></ul>\n  </main>'), TODO_CSS, '// Capstone: when #add is clicked, add the text from #todo\n// to the #list as a new <li>, then clear the input.\nconst input = document.getElementById("todo");\nconst list = document.getElementById("list");\n');
  const L7f = F(L7s['index.html'], TODO_CSS, 'const input = document.getElementById("todo");\nconst list = document.getElementById("list");\ndocument.getElementById("add").addEventListener("click", () => {\n  const text = input.value.trim();\n  if (!text) return;\n  const li = document.createElement("li");\n  li.textContent = text;\n  list.appendChild(li);\n  input.value = "";\n});\n');
  // lesson 8: rollback
  const L8s = F(html('Release 1', '  <main class="hero">\n    <h1>Release 1</h1>\n    <p>Deploy this. Then change the heading to "Release 2" and deploy again.</p>\n  </main>'), BASE_CSS, '');
  // lesson 9: broken file references
