/* ===== Online code runner for Java, Go, Rust, PHP, Ruby, Swift, Kotlin, Bash =====
   These languages cannot run inside a browser tab, so the code is sent to a free public
   code-execution service. Several services are tried in order; the first that answers wins. */
const RemoteRun = (() => {
  const J0 = { java: 62, go: 60, rust: 73, php: 68, ruby: 72, swift: 83, kotlin: 78, bash: 46 };
  const PISTON = { java: 'java', go: 'go', rust: 'rust', php: 'php', ruby: 'ruby', swift: 'swift', kotlin: 'kotlin', bash: 'bash' };
  const WB_LANG = { java: 'Java', go: 'Go', rust: 'Rust', php: 'PHP', ruby: 'Ruby', swift: 'Swift', bash: 'Bash script' };
  const b64e = (t) => { const u = new TextEncoder().encode(String(t)); let s = ''; for (let i = 0; i < u.length; i += 0x8000) s += String.fromCharCode.apply(null, u.subarray(i, i + 0x8000)); return btoa(s); };
  const b64d = (t) => { if (!t) return ''; try { const s = atob(String(t).replace(/\s/g, '')); const u = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) u[i] = s.charCodeAt(i); return new TextDecoder().decode(u); } catch (e) { return ''; } };
  const timed = (url, opt, ms) => { const c = new AbortController(); const t = setTimeout(() => c.abort(), ms || 25000); return fetch(url, Object.assign({}, opt, { signal: c.signal })).finally(() => clearTimeout(t)); };
  const clean = (t) => String(t || '').replace(/\r/g, '').replace(/\n+$/, '');

  async function judge0(lang, code, stdin) {
    if (!J0[lang]) throw new Error('unsupported');
    const body = JSON.stringify({ language_id: J0[lang], source_code: b64e(code), stdin: b64e(stdin || ''), cpu_time_limit: 10, wall_time_limit: 20 });
    const r = await timed('https://ce.judge0.com/submissions?base64_encoded=true&wait=true', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body }, 30000);
    if (!r.ok) throw new Error('judge0 ' + r.status);
    let j = await r.json();
    if (j.token && !j.status) { // wait=true not honoured: poll
      for (let i = 0; i < 20 && (!j.status || j.status.id <= 2); i++) { await new Promise((ok) => setTimeout(ok, 700)); const pr = await timed('https://ce.judge0.com/submissions/' + j.token + '?base64_encoded=true', {}, 15000); j = await pr.json(); }
    }
    if (!j.status) throw new Error('judge0 bad reply');
    const out = clean(b64d(j.stdout)), id = j.status.id;
    let error = '';
    if (id === 6) error = clean(b64d(j.compile_output)) || 'Compilation failed.';
    else if (id === 5) error = 'Time limit exceeded. Does your program loop forever?';
    else if (id > 3) error = clean(b64d(j.stderr)) || clean(b64d(j.message)) || clean(b64d(j.compile_output)) || j.status.description;
    return { out, error };
  }

  let wbList = null;
  async function wandbox(lang, code, stdin) {
    if (!WB_LANG[lang]) throw new Error('unsupported');
    if (!wbList) { const r = await timed('https://wandbox.org/api/list.json', {}, 15000); if (!r.ok) throw new Error('wandbox list'); wbList = await r.json(); }
    const c = wbList.filter((x) => x.language === WB_LANG[lang] && !/head|nightly/i.test(x.name))[0] || wbList.filter((x) => x.language === WB_LANG[lang])[0];
    if (!c) throw new Error('no compiler');
    const r = await timed('https://wandbox.org/api/compile.json', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ compiler: c.name, code, stdin: stdin || '', save: false }) }, 30000);
    if (!r.ok) throw new Error('wandbox ' + r.status);
    const j = await r.json();
    const out = clean(j.program_output || ''); let error = '';
    if (j.compiler_error && String(j.status) !== '0' && !out) error = clean(j.compiler_error);
    else if (String(j.status) !== '0') error = clean(j.program_error || j.compiler_error) || 'The program exited with an error.';
    return { out, error };
  }

  async function piston(lang, code, stdin) {
    const r = await timed('https://emkc.org/api/v2/piston/execute', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ language: PISTON[lang], version: '*', files: [{ content: code }], stdin: stdin || '' }) }, 30000);
    if (!r.ok) throw new Error('piston ' + r.status);
    const j = await r.json(); if (!j.run) throw new Error('piston bad reply');
    const out = clean(j.run.stdout); let error = '';
    if (j.compile && j.compile.code) error = clean(j.compile.stderr || j.compile.output);
    else if (j.run.code) error = clean(j.run.stderr || j.run.output) || 'The program exited with code ' + j.run.code + '.';
    return { out, error };
  }

  // Resolves { out, error }, or rejects when no service could be reached.
  async function run(lang, code, stdin) {
    let last = null;
    for (const p of [judge0, piston, wandbox]) {
      try { const r = await p(lang, code, stdin); r.via = p.name; return r; } catch (e) { last = e; }
    }
    throw last || new Error('offline');
  }
  return { run, langs: Object.keys(J0) };
})();
const NET_MSG = 'Could not reach the online code runner. Java, Go, Rust, PHP, Ruby, Swift, Kotlin and Bash run on a free online service, so they need an internet connection. Check your connection and press Run again.';
// Run any language and always return a Promise of { out, error }.
async function runCodeAsync(lang, code, stdin, setup) {
  if (typeof STATIC_LANGS !== 'undefined' && STATIC_LANGS.includes(lang)) {
    try { return await RemoteRun.run(lang, code, stdin); } catch (e) { return { out: '', error: NET_MSG, offline: true }; }
  }
  return runCode(lang, code, stdin, setup);
}

function runCode(lang, code, stdin, setup) {
  if (lang === 'py') return PyEngine.run(code, stdin);
  if (lang === 'js') return JsEngine.run(code);
  if (lang === 'ts') return TsEngine.run(code);
  if (lang === 'cs') return CsEngine.run(code, stdin);
  if (lang === 'sql') return SqlEngine.run(code, setup || SQL_SHOP);
  if (['java','go','rust','php','ruby','swift','kotlin','bash'].includes(lang)) return { out: '', error: 'This language runs online. Use the Run button.' };  // sync callers never reach here; see runCodeAsync
  return CEngine.run(code, lang, stdin);
}
function makeSession(lang, code, stdin, setup) {
  if (lang === 'py') return PyEngine.session(code + (setup ? '\n' + setup : ''), stdin);
  if (lang === 'js') return JsEngine.session(code + (setup ? '\n' + setup : ''));
  if (lang === 'ts') return TsEngine.session(code + (setup ? '\n' + setup : ''));
  if (lang === 'cs') return CsEngine.session(code, stdin, setup);
  if (['java','go','rust','php','ruby','swift','kotlin','bash'].includes(lang)) return { error: 'This language runs online and has no live session.', evalExpr: () => ({ ok: false, error: 'not available' }) };
  return CEngine.session(code + (setup ? '\n' + setup : ''), lang, stdin);
}
const normalizeOut = (s) => String(s || '').replace(/\r/g, '').split('\n').map((l) => l.replace(/\s+$/, '')).join('\n').replace(/^\n+/, '').replace(/\n+$/, '');
function same(a, b) {
  if (typeof a === 'number' && typeof b === 'number') return Math.abs(a - b) < 1e-9;
  if (Array.isArray(a) && Array.isArray(b)) return a.length === b.length && a.every((x, i) => same(x, b[i]));
  if (a && b && typeof a === 'object' && typeof b === 'object' && !Array.isArray(a) && !Array.isArray(b)) {
    const ka = Object.keys(a).sort(), kb = Object.keys(b).sort();
    return ka.length === kb.length && ka.every((k, i) => k === kb[i] && same(a[k], b[k]));
  }
  return a === b;
}
function showVal(v) { if (v === undefined || v === null) return 'nothing (None / null)'; if (typeof v === 'string') return JSON.stringify(v); try { return JSON.stringify(v); } catch (e) { return String(v); } }

// Grade a Java/Go/Rust/PHP/Ruby/Swift/Kotlin/Bash lesson by really running it online.
async function gradeRemoteLesson(lang, lesson, code, stdin) {
  const r = await runCodeAsync(lang, code, stdin);
  if (r.offline) { // no internet: fall back to comparing with the lesson solution
    const g = gradeLesson(lang, lesson, code, stdin);
    g.run = { out: '', error: NET_MSG + '\n\nYour code was compared with the lesson solution instead.' };
    return g;
  }
  if (r.error) return { pass: false, run: r, results: [], msg: 'Your code has an error. Read the message in the output panel, fix it, and run again.' };
  const want = lesson.expect !== undefined ? lesson.expect : (lesson.check && lesson.check.out);
  if (want === undefined || want === '') return { pass: !!r.out || staticCoverage(lesson.solution, code, lesson.starter).ratio >= 0.9, run: r, results: [], msg: 'Your program printed nothing. Follow the task and print the result.' };
  const ok = normalizeOut(r.out) === normalizeOut(want);
  return ok ? { pass: true, run: r, results: [] } : { pass: false, run: r, results: [], msg: 'The output is not what the task asks for yet.', expected: want, got: r.out };
}
const STATIC_LANGS = ['java','go','rust','php','ruby','swift','kotlin','bash'];
function codeTokens(src) {
  const t = String(src || '').replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/(^|[^:"'$])\/\/.*$/gm, '$1').replace(/(^|\s)#(?![{!]).*$/gm, '$1').replace(/^#(?!!).*$/gm, '');
  const re = /"(?:[^"\\\n]|\\.)*"|'(?:[^'\\\n]|\\.)*'|\$\{[^}]*\}|[A-Za-z_$@][\w$]*|\d+(?:\.\d+)?|==|!=|<=|>=|&&|\|\||\+\+|--|\+=|-=|\*=|\/=|->|=>|::|\.\.\.|\.\.|>>|<<|[-+*\/%=<>!(){}\[\]:.,|&?~^]/g;
  return (t.match(re) || []).map((x) => ((x[0] === '"' || x[0] === "'") ? 's:' + x.slice(1, -1) : x));
}
function lcsMatch(A, B) {
  const n = A.length, m = B.length, dp = []; for (let i = 0; i <= n; i++) dp.push(new Uint16Array(m + 1));
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) dp[i][j] = A[i] === B[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const hit = new Array(n).fill(false); let i = 0, j = 0;
  while (i < n && j < m) { if (A[i] === B[j]) { hit[i] = true; i++; j++; } else if (dp[i + 1][j] >= dp[i][j + 1]) i++; else j++; }
  return hit;
}
function staticCoverage(solution, code, starter) {
  const A = codeTokens(solution), B = codeTokens(code), S = codeTokens(starter || '');
  const free = lcsMatch(A, S), got = lcsMatch(A, B);
  const need = []; A.forEach((t, i) => { if (!free[i]) need.push(i); });
  const missing = need.filter((i) => !got[i]).map((i) => A[i].replace(/^s:/, '"') + (A[i].indexOf('s:') === 0 ? '"' : ''));
  const overall = A.length ? got.filter(Boolean).length / A.length : 1;
  const ratio = need.length ? (need.length - missing.length) / need.length : 1;
  return { ratio: Math.min(ratio, overall >= 0.8 ? ratio : overall), missing };
}
function gradeLesson(lang, lesson, code, stdin) {
  if (lang === 'sql') return gradeSql(lesson, code);
  if (STATIC_LANGS.includes(lang)) {
    const cov = staticCoverage(lesson.solution, code, lesson.starter); const ok = cov.ratio >= 0.9;
    const note = 'Live execution is not available for this language yet, so your code is compared with the lesson solution instead of being run.' + (ok && lesson.expect ? '\n\nWhen this program runs it prints:\n' + lesson.expect : '');
    return { pass: ok, run: { out: note, output: note, error: null }, results: [], msg: ok ? null : 'Not quite yet: your code is missing parts the task needs, such as ' + cov.missing.slice(0, 4).join(', ') + '. Use the hint if you are stuck.' };
  }
  const r = runCode(lang, code, stdin);
  if (r.error) return { pass: false, run: r, results: [], msg: 'Your code has an error. Read the message in the output panel, fix it, and run again.' };
  const ck = lesson.check || {}; const results = []; let msg = null, expected, got;
  if (ck.out !== undefined) {
    const ok = normalizeOut(r.out) === normalizeOut(ck.out);
    if (!ok) { msg = 'The output is not what the task asks for yet.'; expected = ck.out; got = r.out; }
  }
  for (const [expr, exp, setup] of ck.tests || []) {
    const s = makeSession(lang, code, stdin, setup);
    let ok = false, gotTxt = '';
    if (s.error) gotTxt = 'error: ' + s.error;
    else { const e = s.evalExpr(expr); if (!e.ok) gotTxt = 'error: ' + e.error; else { ok = same(e.value, exp); gotTxt = showVal(e.value); } }
    results.push({ label: expr, setup: setup || '', ok, exp: showVal(exp), got: gotTxt });
    if (!ok && !msg) msg = 'Not every test passes yet. Check the list below: the first failing test shows what your code returned.' + (gotTxt === showVal(undefined) ? ' Did you forget to return a value?' : '');
  }
  const pass = msg === null && results.every((x) => x.ok);
  return { pass, run: r, results, msg, expected, got };
}
function sameRows(a, b, ordered) {
  const norm = (rows) => rows.map((r) => r.map((v) => (typeof v === 'number' ? Math.round(v * 1e9) / 1e9 : v)));
  let x = norm(a), y = norm(b);
  if (!ordered) { const k = (r) => JSON.stringify(r); x = x.slice().sort((p, q) => (k(p) < k(q) ? -1 : 1)); y = y.slice().sort((p, q) => (k(p) < k(q) ? -1 : 1)); }
  return JSON.stringify(x) === JSON.stringify(y);
}
function fmtRows(rows, cols) { return SqlEngine.formatRows({ cols: cols || rows[0].map((_, i) => 'col' + (i + 1)), rows }); }
function gradeSql(les, code) {
  const r = SqlEngine.run(code, les.setup);
  if (r.error) return { pass: false, run: r, results: [], msg: 'Your query has an error. Read the message in the output panel, fix it, and run again.' };
  const lr = SqlEngine.lastRows(les.setup, code, les.check.verify);
  if (lr.error) return { pass: false, run: r, results: [], msg: lr.error };
  if (!lr.res) return { pass: false, run: r, results: [], msg: 'Your code did not produce a result table. Write a SELECT query.' };
  const want = les.check.rows; const got = lr.res.rows; const ok = sameRows(got, want, les.check.ordered !== false);
  if (ok) return { pass: true, run: r, results: [] };
  const colsGuess = lr.res.cols;
  const widthOk = got.length === 0 || got[0].length === want[0].length;
  return { pass: false, run: r, results: [], msg: !widthOk ? `Your query returns ${got[0].length} column${got[0].length === 1 ? '' : 's'} but the task needs ${want[0].length}.` : got.length !== want.length ? `Your query returns ${got.length} row${got.length === 1 ? '' : 's'}; the task expects ${want.length}.` : (les.check.ordered !== false ? 'The rows are right in number, but the values or their order differ.' : 'The rows are the right size, but some values differ.'), expected: fmtRows(want, widthOk ? colsGuess : null), got: SqlEngine.formatRows(lr.res) };
}
function sqlQuizText(setup, sql) {
  const lr = SqlEngine.lastRows(setup, sql, null); if (lr.error) return 'ERROR ' + lr.error; if (!lr.res) return 'no rows';
  if (!lr.res.rows.length) return '(no rows)';
  return lr.res.rows.map((r) => r.map((v) => (v === null ? 'NULL' : typeof v === 'number' ? String(Math.round(v * 1e10) / 1e10) : String(v))).join('|')).join(', ');
}
const HEAD = {
  c: '#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n\n',
  cpp: '#include <iostream>\n#include <string>\n#include <vector>\n#include <map>\n#include <algorithm>\nusing namespace std;\n\n',
};
/* 4.3: bank questions put the real question in a leading comment ("// Which keyword declares a class?"), followed by
   any code it needs (unrelated filler was removed from ranked_extra.json). Show the comment as the question and the
   rest as code. Labels like "Predict the output" and "Find the bug" become the heading. */
function quizShow(lang, q) { const r = quizShow0(lang, q); r.ask = r.ask.charAt(0).toUpperCase() + r.ask.slice(1); return r; }
function quizShow0(lang, q) {
  const code = String((q && q.code) || ''); const lines = code.split('\n'); const m = /^\s*(?:\/\/|#|--)\s*(.+?)\s*$/.exec(lines[0] || ''); const rest = lines.slice(1).join('\n').replace(/^\s*\n|\s+$/g, '');
  const wrap = (c) => (c ? quizProgram(lang, Object.assign({}, q, { code: c })).display : '');
  if (m) { const label = m[1];
    if (/\?$/.test(label)) return { ask: label, display: wrap(rest) };
    if (/^predict\b/i.test(label)) return { ask: lang === 'sql' ? 'what does this return?' : 'what does this print?', display: wrap(rest) };
    if (/^(find the (bug|error|mistake|issue)|diagnose the (issue|problem))/i.test(label)) return { ask: 'what is wrong with this code?', display: wrap(rest) };
  }
  return { ask: quizAsk(q), display: quizProgram(lang, q).display };
}
function quizAsk(q) {
  const c = String((q && q.code) || '');
  if (/print|echo|puts|console\.|println|printf|cout|Console\.Write|\bSELECT\b|\bsay\b|fmt\./i.test(c)) return 'what does this print?';
  const o = String((q && q.options && q.options[q.answer]) || ''); return o.length <= 28 ? 'what does this give?' : 'which statement is true?';
}
function quizProgram(lang, q) {
  if (lang !== 'c' && lang !== 'cpp' && lang !== 'cs') return { display: q.code, run: q.code }; // Java, Go, Rust and others are shown as written, never wrapped in a C main()
  if (lang === 'cs') { const t = (q.pre ? q.pre + '\n' : '') + q.code; return { display: t, run: t }; }
  const ind = (s) => s.split('\n').map((l) => '    ' + l).join('\n');
  const main = (lang === 'c' ? 'int main(void) {\n' : 'int main() {\n') + ind(q.code) + '\n    return 0;\n}';
  const body = (q.pre ? q.pre + '\n\n' : '') + main;
  return { display: body, run: HEAD[lang] + body };
}

/* friendly explanations for common error messages */
const TIPS = {
  common: [
    [/NameError|undeclared|is not defined/i, 'You used a name the computer has never heard of. Check the spelling and capital letters, and make sure the variable or function is created before this line.'],
    [/IndentationError|unexpected indent|expected an indented block/i, 'Python uses indentation to group lines. The lines inside an if, for, def or class must be indented (4 spaces) and lined up with each other.'],
    [/SyntaxError|Unexpected token|Unexpected identifier|invalid syntax/i, 'The code is not written in a shape the language understands. Look at the line mentioned (and the one before it) for a missing colon, bracket, quote or comma.'],
    [/expected '[;)\]}]'|expected ';'/i, 'A symbol is missing. Statements in C and C++ end with a semicolon, and every opening bracket needs its partner. The real mistake is often on the line above the one reported.'],
    [/ZeroDivision|division by zero|modulo by zero/i, 'You divided by zero, which has no answer. Check the value of the bottom number before dividing, or handle the zero case separately.'],
    [/IndexError|out of bounds|out of range/i, 'You asked for a position that does not exist. Counting starts at 0, so a list or array of n items only has positions 0 to n - 1.'],
    [/KeyError/i, 'That key is not in the dictionary. Check the spelling, or use .get(key) which returns None instead of failing.'],
    [/TypeError.*(unsupported operand|can only concatenate)|Cannot convert|invalid operands/i, 'You mixed incompatible types, like adding text to a number. Convert one side first, for example str(5) or int("5").'],
    [/ValueError.*invalid literal|could not convert/i, 'That text cannot be turned into a number. Check what the string really contains (spaces and letters are not digits).'],
    [/AttributeError|has no attribute|has no member/i, 'The thing you used a dot on does not have that name. Check the spelling, and check what type of value it really is.'],
    [/is not a function|not callable/i, 'You tried to call something that is not a function. Check for a typo, or a variable that has the same name as a function.'],
    [/RecursionError|Stack overflow|call stack/i, 'A function kept calling itself without stopping. Every recursive function needs a base case that returns without another recursive call.'],
    [/ran for too long|infinite loop/i, 'The program never finished. Look at your loop condition: something inside the loop must change so that it eventually becomes false.'],
    [/Segmentation fault|NULL pointer/i, 'The program followed a pointer that points nowhere (NULL). Check that the pointer was set to a real address before you used it.'],
    [/implicit declaration/i, 'The function is unknown here. Check the spelling, and make sure the right #include line is at the top of the file.'],
    [/too (few|many) arguments|takes \d+ positional|missing \d+ required/i, 'The number of arguments in the call does not match the function. Count the parameters in the definition and the values in the call.'],
    [/EOFError|EOF when reading/i, 'The program asked for input but there was none. Open "Program input" and type some text there first.'],
    [/threw an exception|terminate/i, 'An exception was thrown and nothing caught it. Wrap the risky call in try { ... } catch (...) { ... }.'],
    [/buffer overflow|too small/i, 'You tried to put more characters into an array than it can hold. Make the array bigger (remember the extra spot for the final \\0).'],
  ],
};
function explainError(lang, text) {
  if (!text) return null;
  for (const [re, tip] of TIPS.common) if (re.test(text)) return tip;
  return null;
}

