function badgeXp() { let t = 0; for (const b of BADGES) if (S.badges && S.badges[b.id]) t += b.xp; return t; }
function checkBadges() {
  const fresh = [];
  for (let pass = 0; pass < 4; pass++) {
    let any = false;
    for (const b of BADGES) { let ok = false; try { ok = !S.badges[b.id] && b.test(); } catch (e) { ok = false; } if (ok) { S.badges[b.id] = true; fresh.push(b); any = true; } }
    if (!any) break;
  }
  if (fresh.length) save(); return fresh;
}
function badgeToast(fresh) {
  const xpSum = fresh.reduce((n, b) => n + b.xp, 0);
  toast('🏆 Achievement unlocked: <b>' + fresh.slice(0, 3).map((b) => b.icon + ' ' + esc(b.name)).join(', ') + (fresh.length > 3 ? ' +' + (fresh.length - 3) + ' more' : '') + '</b> · +' + xpSum + ' XP');
  const xpEl = $('.xpchip'); if (xpEl) xpEl.textContent = '⭐ ' + xp() + ' XP';
}
function awardCheck() { const fresh = checkBadges(); if (fresh.length) badgeToast(fresh); return fresh; }
setInterval(() => { try { awardCheck(); } catch (e) {} }, 5000);
function achievementsHtml() {
  const got = BADGES.filter((b) => S.badges[b.id]), gotXp = got.reduce((n, b) => n + b.xp, 0), allXp = BADGES.reduce((n, b) => n + b.xp, 0);
  const groups = BADGE_DIFF_ORDER.map((d) => {
    const list = BADGES.filter((b) => b.diff === d), on = list.filter((b) => S.badges[b.id]).length, D = BADGE_DIFF[d];
    const cards = list.slice().sort((a, b) => (S.badges[b.id] ? 1 : 0) - (S.badges[b.id] ? 0 : 1) || 0).sort((a, b) => (S.badges[b.id] ? 0 : 1) - (S.badges[b.id] ? 1 : 0)).map((b) => {
      let p = null; if (!S.badges[b.id] && b.prog) { try { p = b.prog(); } catch (e) { p = null; } }
      return '<div class="ach' + (S.badges[b.id] ? ' on' : '') + '" title="' + esc(b.desc) + '"><span class="ic">' + b.icon + '</span><b>' + esc(b.name) + '</b><small>' + esc(b.desc) + '</small><span class="achx" style="--dc:' + D.c + '">' + D.name + ' · ' + (S.badges[b.id] ? '+' + b.xp + ' XP earned' : '+' + b.xp + ' XP') + '</span>' + (p ? '<span class="achp"><i style="width:' + Math.round(Math.min(1, p[0] / p[1]) * 100) + '%"></i></span><small class="achn">' + Math.floor(p[0]) + ' / ' + p[1] + '</small>' : '') + '</div>';
    }).join('');
    return '<details class="achg"><summary><span class="achd" style="--dc:' + D.c + '">' + D.name + '</span> ' + on + ' / ' + list.length + ' · +' + D.xp + ' XP each</summary><div class="badges">' + cards + '</div></details>';
  }).join('');
  // 5.1: show the four achievements closest to unlocking; the full list is in the closed groups below
  const duelPlayed = (() => { const d = S.duel || {}; return (d.w || 0) + (d.l || 0) + (d.d || 0) > 0; })();
  const near = BADGES.filter((b) => !S.badges[b.id] && b.prog && (duelPlayed || !/^rate\d/.test(b.id))).map((b) => { let p = null; try { p = b.prog(); } catch (e) {} return { b, f: p && p[1] ? Math.min(1, (p[0] || 0) / p[1]) : 0, p }; }).filter((x) => x.f > 0).sort((a, b) => b.f - a.f).slice(0, 4);
  const nearHtml = near.length ? '<h3 class="achnear-h">Closest to unlocking</h3><div class="badges achnear">' + near.map(({ b, p }) => { const D = BADGE_DIFF[b.diff]; return '<div class="ach" title="' + esc(b.desc) + '"><span class="ic">' + b.icon + '</span><b>' + esc(b.name) + '</b><small>' + esc(b.desc) + '</small><span class="achx" style="--dc:' + D.c + '">' + D.name + ' · +' + b.xp + ' XP</span><span class="achp"><i style="width:' + Math.round(Math.min(1, (p[0] || 0) / p[1]) * 100) + '%"></i></span><small>' + (p[0] || 0) + ' / ' + p[1] + '</small></div>'; }).join('') + '</div>' : '';
  return '<h2 class="sect">Achievements</h2><p class="pill" style="font-size:15px">🏆 <b>' + got.length + ' / ' + BADGES.length + '</b> unlocked · ' + gotXp + ' of ' + allXp + ' bonus XP earned. Harder achievements give more XP.</p>' + nearHtml + '<p class="muted" style="margin:14px 0 6px">All achievements, by difficulty (tap to open):</p>' + groups;
}
