    const tabsEl = $c('.cl-tabs'), edHost = $c('.cl-ed'), dash = $c('.cdash'), linesEl = $c('.cd-lines'), sideEl = $c('.cd-side'), resEl = $c('.cd-result'), histEl = $c('.cd-hist'), pill = $c('.cd-pill');
