      if (line) { const ta = edHost.querySelector('textarea'); const ls = files[f].split('\n'); let pos = 0; for (let i = 0; i < line - 1 && i < ls.length; i++) pos += ls[i].length + 1; ta.focus(); ta.setSelectionRange(pos, pos + (ls[line - 1] || '').length); const lh = parseFloat(getComputedStyle(ta).lineHeight) || 22; ta.scrollTop = Math.max(0, (line - 3) * lh); ta.dispatchEvent(new Event('scroll')); }
