      modal = document.createElement('div'); modal.className = 'cd-modal'; modal.setAttribute('role', 'dialog'); modal.setAttribute('aria-modal', 'true'); modal.setAttribute('aria-label', 'Live preview of ' + d.url);
      modal.innerHTML = '<div class="cd-browser"><div class="cd-chrome"><span class="d r"></span><span class="d y"></span><span class="d g"></span><div class="cd-addr"><span aria-hidden="true">🔒</span><code>' + E(d.url) + '</code></div><button type="button" class="cd-x2" data-m="reload" aria-label="Reload preview">⟳</button><button type="button" class="cd-x2" data-m="close" aria-label="Close preview">✕</button></div><iframe class="cd-frame" title="Live preview" sandbox="allow-scripts allow-forms"></iframe><div class="cd-foot"><span>● Served from the edge · yyz1 · ' + d.edge + ' ms · HTTP/3 · TLS 1.3</span><span class="cd-cons">Console: 0 errors</span></div></div>';
