    '<div class="syms" role="group" aria-label="Quick keys"><button type="button" class="sym" data-ins="    " aria-label="Insert tab">Tab</button>' + (SYMS[lang] || SYMS_DEFAULT).map((s) => '<button type="button" class="sym" data-ins="' + esc(s) + '">' + esc(s) + '</button>').join('') + '</div>';
  const ed = $('.editor', host), pre = $('pre', host), code = $('code', pre), ta = $('textarea', host), gnum = $('.gnum', host);
  const paint = () => {
    code.innerHTML = hl(ta.value, lang) + '\n';
    const lines = ta.value.split('\n').length; let nums = ''; for (let i = 1; i <= lines; i++) nums += i + '\n'; gnum.textContent = nums;
    const lh = parseFloat(getComputedStyle(ta).lineHeight) || 22; ed.style.height = Math.max(190, Math.min(480, lines * lh + 30)) + 'px';
  };
  const sync = () => { const t = 'translate(' + (-ta.scrollLeft) + 'px,' + (-ta.scrollTop) + 'px)'; pre.style.transform = t; gnum.style.transform = 'translateY(' + (-ta.scrollTop) + 'px)'; };
