const EXTRA_LESSON_QUESTIONS = {"py":[["What does `range(3)` produce when iterated?",["0, 1, 2","1, 2, 3","0, 1, 2, 3","Only 3"],0,"range(3) starts at zero and stops before three."],["Which structure stores key-value pairs?",["tuple","set","dict","list"],2,"A dict maps keys to values."],["What does `len([4, 5, 6])` return?",["2","3","4","6"],1,"There are three elements in the list."]],"js":[["What does `const` prevent?",["Changing an object’s nested properties in all cases","Reassigning the binding","Using arrays","Declaring strings"],1,"const prevents rebinding the variable; object contents may still change."],["What is `typeof 42`?",["number","int","integer","numeric"],0,"JavaScript numbers use the number type."],["Which method adds an item to the end of an array?",["append()","push()","insertEnd()","addLast()"],1,"Array.prototype.push adds one or more items to the end."]],"ts":[["What does `string | number` describe?",["A string converted to a number","A union that may be either type","An array of both types","A type error"],1,"A union type allows a value to be either string or number."],["Which modifier makes a property optional?",["!","?","*","&"],1,"A question mark marks an optional property."],["What does `unknown` require before using a value as a string?",["No checks","A type guard or assertion","A semicolon only","A class declaration"],1,"unknown is safer than any and requires narrowing before specific operations."]],"c":[["Which function safely reads a line with a size limit into a buffer?",["gets","fgets","readline","scanline"],1,"fgets accepts a maximum size and helps prevent buffer overflow."],["What does `sizeof(char)` equal in C?",["0","1","2","It depends on the compiler"],1,"The C standard defines sizeof(char) as 1 byte."],["Which symbol accesses a struct member through a pointer?",[".","->","::","=>"],1,"The arrow operator dereferences a pointer to access a member."]],"cpp":[["Which container grows dynamically and stores elements contiguously?",["std::vector","std::tuple","std::array only","std::optional"],0,"std::vector is a dynamic contiguous sequence container."],["What does `const` on a reference usually express?",["The referenced value cannot be modified through that reference","The object is always global","The variable is deleted","The value is random"],0,"A const reference prevents mutation through that reference."],["Which smart pointer expresses exclusive ownership?",["std::weak_ptr","std::shared_ptr","std::unique_ptr","std::raw_ptr"],2,"unique_ptr represents exclusive ownership."]],"cs":[["Which keyword creates an object instance?",["class","new","using","namespace"],1,"new creates an instance of a reference type."],["Which collection stores unique values?",["List<T>","Queue<T>","HashSet<T>","Stack<T>"],2,"HashSet<T> stores distinct elements."],["What does `async` commonly pair with to wait for a Task?",["yield","await","defer","pause"],1,"await asynchronously waits for a task-like operation."]],"sql":[["Which clause filters groups after aggregation?",["WHERE","HAVING","FROM","ORDER BY"],1,"HAVING filters grouped/aggregated results."],["What does `COUNT(*)` count?",["Only non-NULL values in one column","Rows","Distinct tables","Columns in a schema"],1,"COUNT(*) counts rows, including rows with NULL values."],["Which join keeps all rows from the left table?",["INNER JOIN","LEFT JOIN","CROSS JOIN","SELF JOIN"],1,"LEFT JOIN preserves every left-side row and matches right-side rows when available."]],"java":[["Which type stores true or false?",["int","String","boolean","char"],2,"boolean represents true or false."],["What is the first valid array index?",["-1","0","1","It depends on array size"],1,"Java arrays are zero-indexed."],["Which keyword indicates a subclass inherits from a class?",["implements","extends","inherits","superclass"],1,"A class uses extends to inherit from another class."]],"go":[["Which keyword declares a function?",["func","fn","def","function"],0,"Go uses func for function declarations."],["What does `defer` do?",["Runs a call when the surrounding function returns","Starts a goroutine immediately","Declares a constant","Catches all errors"],0,"Deferred calls run as the surrounding function returns."],["Which built-in type represents a sequence of bytes?",["byte[] only","[]byte","bytestring","char*"],1,"[]byte is a slice of bytes."]],"rust":[["Which keyword declares a function?",["func","fn","def","lambda"],1,"Rust function declarations use fn."],["What does `mut` allow on a binding?",["Mutation/reassignment where the type permits it","Automatic cloning","Public visibility","Heap allocation always"],0,"mut marks a binding as mutable."],["What is `Option<T>` used to represent?",["Only errors","A value that may be Some(T) or None","A thread","A mutable reference only"],1,"Option<T> models an optional value without null."]],"php":[["Which symbol starts a PHP variable name?",["$","#","@","%"],0,"PHP variable names start with a dollar sign."],["Which operator concatenates strings in PHP?",["+",".","&","::"],1,"PHP uses the dot operator for string concatenation."],["Which superglobal commonly contains query-string parameters?",["$_POST","$_GET","$_FILES","$_SESSION only"],1,"$_GET contains parameters from the URL query string."]],"ruby":[["Which keyword defines a method?",["def","func","method","lambda"],0,"Ruby uses def to define methods."],["What does `each` commonly do?",["Iterates over collection elements","Sorts every collection","Deletes duplicates","Converts all values to strings"],0,"each yields each item to a block."],["Which value represents absence/false-like nil?",["null","None","nil","void"],2,"Ruby uses nil for the absence of a value."]],"swift":[["Which keyword declares a value that can be reassigned?",["let","var","val","mut"],1,"var declares a mutable variable."],["What does an optional type such as `String?` represent?",["A string or no value (nil)","A string array","A constant string","A non-empty string only"],0,"An optional can hold a value or nil."],["Which keyword handles errors with a throwing call?",["try","catch-only","throws!","error"],0,"Swift uses try when calling a throwing function."]],"kotlin":[["Which keyword declares a read-only local binding?",["var","let","val","const"],2,"val cannot be reassigned after initialization."],["Which operator safely accesses a nullable receiver?",["!!","?.","??","::"],1,"The safe-call operator ?. avoids dereferencing null."],["What does `data class` automatically provide?",["Only a main function","Common value methods such as equals and copy","A database connection","Thread safety"],1,"Data classes generate useful value-oriented methods."]],"bash":[["What is the correct assignment syntax?",["count = 2","count=2","let count := 2","set count = 2"],1,"Shell variable assignment has no spaces around the equals sign."],["Which syntax expands a variable named `name`?",["#name","$name","%name","&name"],1,"Use $name or ${name} to expand a shell variable."],["What does `chmod +x script.sh` do?",["Deletes the script","Adds executable permission","Runs the script immediately","Changes the file extension"],1,"chmod +x adds executable permission bits."]]};
