        h += '<div class="ws-pk"><div class="top"><b>' + esc(n) + '</b><span class="v">' + (v ? esc(v) : esc(r.deps[n] || '')) + '</span>' + chip + '<button class="ws-pb alt" data-pk="' + (v ? 'rm:' : 'add:') + esc(n) + '">' + (v ? 'Remove' : 'Install') + '</button></div></div>';
