        st.tabs.map((p) => '<div class="ws-tab' + (p === st.active ? ' on' : '') + '" role="tab" data-p="' + esc(p) + '">' + badge(basename(p)) + '<span>' + esc(basename(p)) + '</span><button data-x="1" aria-label="Close ' + esc(basename(p)) + '">×</button></div>').join('');
