function buyEmote(id) {
  const r = EMOTES.find((x) => x.id === id); if (!r || S.owned[id] || wallet() < r.cost) return;
  if (!shopToday().all.includes(id)) { toast('That item has left the shop.'); return; }
  S.owned[id] = true; S.spent = (S.spent || 0) + r.cost; { const L = lkInit(); if (L.emotes.length < LOADOUT_MAX) L.emotes.push(id); } save(); toast('😀 Unlocked ' + r.e + ' <b>' + r.n + '</b> for quick chat');
}
function emoteShopHtml(w) {
  return '<h2 class="sect" style="margin-top:26px">😀 Chat emojis</h2><p class="pill" style="font-size:15px">Buy emojis to send in Multiplayer quick chat. Everyone starts with ' + FREE_EMOTES.join(' ') + '.</p><div class="shopgrid emgrid">' +
    EMOTES.map((r) => '<div class="card shopitem emcard"><div class="embig" aria-hidden="true">' + r.e + '</div><h3>' + r.n + '</h3>' + (S.owned[r.id] ? '<span class="pill" style="font-weight:800">✓ Owned</span>' : '<button class="btn small primary" data-buye="' + r.id + '"' + (w < r.cost ? ' disabled' : '') + '>Buy · ' + r.cost + ' XP</button>') + '</div>').join('') + '</div>';
}
function applyRewards() { document.documentElement.dataset.reward = S.equip.accent || ''; }
function titleHtml() { const r = REWARDS.find((x) => x.id === S.equip.title); return r ? '<span class="ttitle">' + r.text + '</span>' : ''; }
function buy(id) {
  const r = REWARDS.find((x) => x.id === id); if (!r || wallet() < r.cost) return;
  if (r.kind === 'repair') {
    const d = new Date(); d.setDate(d.getDate() - 1); const y = dayStr(d);
    if (S.days.includes(y)) { toast('Yesterday already counts, no repair needed.'); return; }
    S.days.push(y);
  } else { if (S.owned[id]) return; S.owned[id] = true; S.equip[r.kind] = id; }
  S.spent = (S.spent || 0) + r.cost; save(); toast('🎁 Purchased: <b>' + r.name + '</b>');
}

