async function redeemCode(raw) {
  const code = duelClean(raw, 16); if (code.length < 4) return 'Type a code first.';
  S.redeemed = S.redeemed || {}; if (S.redeemed[code]) return 'You already used that code.';
  const me = duelMe(); let c;
  try { c = await dbGet('codes/' + code); } catch (e) { return 'Could not reach the online service.'; }
  if (!c || !c.r) return 'That code does not exist.';
  if (c.exp && Date.now() > c.exp) return 'That code has expired.';
  const u = c.u || {};
  if (u[me.uid]) { S.redeemed[code] = true; save(); return 'You already used that code.'; }
  if (c.max && Object.keys(u).length >= c.max) return 'That code has been fully used.';
  try {
    await dbPut('codes/' + code + '/u/' + me.uid, 1);
    const c2 = await dbGet('codes/' + code);
    if (c.max && Object.keys((c2 && c2.u) || {}).length > c.max) { await dbDel('codes/' + code + '/u/' + me.uid).catch(() => {}); return 'That code has been fully used.'; }
  } catch (e) { return 'Could not reach the online service.'; }
  S.redeemed[code] = true; fbAudit('code-redeem', code);
  const msg = grantReward(c.r); save(); return '🎉 ' + msg;
}
