const AVATAR_FREE = AVATAR_ITEMS.filter(x=>x.cost===0).map(x=>x.id);
function avatarInit(){
  const raw = (S.avatar && typeof S.avatar === 'object') ? S.avatar : {};
  S.avatar = Av3D.clean(raw);
  const own = (S.avatarOwned && typeof S.avatarOwned === 'object') ? S.avatarOwned : {};
  S.avatarOwned = Object.assign({}, own); AVATAR_FREE.forEach(id => { S.avatarOwned[id] = true; });
  for (const k of Object.keys(S.avatar)) { if (!S.avatarOwned[S.avatar[k]]) S.avatar[k] = Av3D.DEF[k]; }
}
function avatarPreview(a){
  avatarInit();
  return '<div class="avatar-stage"><canvas class="avatar-canvas" id="avatarCanvas" tabindex="0" role="img" aria-label="Your 3D avatar. Drag to turn it, tap to make it wave and jump."></canvas><div class="av-caption">Drag to turn · tap to wave</div><div class="av-tools"><button class="btn small" id="avRandom" type="button">🎲 Surprise me</button><button class="btn small" id="avReset" type="button">↺ Reset look</button></div></div>';
}
function avatarMountCanvas(){ const cv = document.getElementById('avatarCanvas'); if (!cv) return; try { Av3D.mount(cv, () => S.avatar); } catch (e) { cv.replaceWith(Object.assign(document.createElement('p'), { className: 'pill', textContent: 'Your browser could not start the 3D preview.' })); } }
function avatarThumbImg(x){
  if (!x) return '<span class="av-thumb"></span>';
  if (x.cat === 'stage') { const th = Av3D.STAGES[x.id]; return '<span class="av-thumb" style="display:block;border-radius:12px;background:' + (th ? th.sw : '#333') + '"></span>'; }
  return '<img class="av-thumb" alt="" width="76" height="76" data-avt="' + x.id + '" src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==">';
}
let avThumbBusy = false;
function fillThumbs() {
  if (avThumbBusy) return; avThumbBusy = true;
  (function step() {
    const all = Array.from(document.querySelectorAll('img[data-avt]:not([data-done])'));
    if (!all.length) { avThumbBusy = false; return; }
    const vh = window.innerHeight || 800;
    all.sort((a, b) => Math.abs(a.getBoundingClientRect().top - vh / 2) - Math.abs(b.getBoundingClientRect().top - vh / 2));
    all.slice(0, 3).forEach((img) => { img.dataset.done = '1'; const it = AVATAR_ITEMS.find((z) => z.id === img.dataset.avt); try { const u = it && Av3D.thumb(it, S.avatar, 76); if (u) img.src = u; } catch (e) {} });
    setTimeout(step, 12);
  })();
}
try { new MutationObserver(() => { if (document.querySelector('img[data-avt]:not([data-done])')) fillThumbs(); }).observe(document.getElementById('app') || document.body, { childList: true, subtree: true }); } catch (e) {}
function avatarMini(a){
  let u = ''; try { u = a ? Av3D.bust(Av3D.clean(a), 40) : Av3D.bust({}, 40); } catch (e) { u = ''; }
  return '<span class="friend-avatar2d" title="Friend avatar">' + (u ? '<img alt="" src="' + u + '">' : '') + '</span>';
}
