 const rnd=$('#avRandom'); if(rnd) rnd.addEventListener('click',()=>{avatarInit();const pick=(cat)=>{const o=AVATAR_ITEMS.filter(i=>i.cat===cat&&S.avatarOwned[i.id]);return o[Math.floor(Math.random()*o.length)].id;};Object.keys(Av3D.DEF).forEach(c=>{S.avatar[c]=pick(c);});save();const y=window.scrollY;renderAvatar();window.scrollTo(0,y);});
 const rst=$('#avReset'); if(rst) rst.addEventListener('click',()=>{S.avatar=Object.assign({},Av3D.DEF);save();const y=window.scrollY;renderAvatar();window.scrollTo(0,y);});
