function avShopGroups(items,w){return AV_CATS.map(([cat,label],gi)=>{const list=items.filter(x=>x.cat===cat);if(!list.length)return '';const own=list.filter(x=>S.avatarOwned[x.id]).length;return '<details class="achg"'+(gi===5?' open':'')+'><summary><b>'+label+'</b> <span class="pill">'+own+' / '+list.length+' owned</span></summary><div class="shopgrid">'+list.map(x=>avCard(x,w)).join('')+'</div></details>';}).join('');}
