 $$('[data-buy]').forEach((b)=>b.addEventListener('click',()=>{buy(b.dataset.buy);applyRewards();renderShop();}));
 $$('[data-buye]').forEach((b)=>b.addEventListener('click',()=>{buyEmote(b.dataset.buye);renderShop();}));
 $$('[data-lkbuy]').forEach((b)=>b.addEventListener('click',()=>{const y=window.scrollY;lkBuy(b.dataset.lkbuy);renderShop();window.scrollTo(0,y);}));
