/* ----- practice match against the computer (1v1, no rank change) ----- */
function duelStart(lang) {
  const d = duelInit(); d.lang = lang; save();
  const botR = Math.max(0, d.r + Math.round((Math.random() - 0.5) * 160));
  const acc = Math.min(0.93, Math.max(0.5, 0.5 + (botR - 700) / 2000));
  const mean = Math.min(10, Math.max(3.5, 11 - (botR - 700) / 150));
  const qs = duelPickRefs(lang === 'mix' ? LANG_ORDER : [lang], DUEL_N).map(([k, i]) => {
    const q = duelLangPool(k)[i]; const idx = duelShuf(q.options.map((_, i) => i));
    return { k, q, opts: idx.map((i) => q.options[i]), ans: idx.indexOf(q.answer),
      bot: { ok: Math.random() < acc, t: Math.min(DUEL_T - 0.5, Math.max(1.5, mean * (0.65 + Math.random() * 0.7))) } };
  });
  const name = BOT_NAMES[Math.floor(Math.random() * BOT_NAMES.length)];
  DU = { active: true, mode: 'bot', kind: 'bot', n: 1, ranked: false, stage: 'play', lang, T: DUEL_T, NQ: DUEL_N, i: 0, qs, me: 0, bot: 0, botR, name, res: [], answered: false, over: null };
  renderDuel();
}
function awardMultiplayerXP(result, matchKey){ if(!result || result==='forfeit') return 0; S.mpRewards=S.mpRewards||{}; const key=String(matchKey||'match')+'|'+String(result); if(S.mpRewards[key]) return 0; const amount=result==='win'?30:result==='draw'?15:10; S.mpRewards[key]=true; S.bonus=(S.bonus||0)+amount; save(); return amount; }
function duelFinish(forfeit) {
  const D = DU; duelStop(); D.active = false;
  const res = forfeit ? 'loss' : D.me > D.bot ? 'win' : D.me < D.bot ? 'loss' : 'draw';
  D.over = duelNoRank(1, res, { name: D.name, lang: D.lang, me: D.me, bot: D.bot, ff: forfeit ? 1 : 0, k: 'bot' });
  D.over.forfeit = !!forfeit; renderDuel();
}

/* ----- online matches (1v1 to 4v4) ----- */
/* Team matches: every question slot has one random level, everyone gets that level, but each player gets a different question. */
const DUEL_LEVELS = ['beginner', 'intermediate', 'pro'];
