    const k = ls[Math.floor(Math.random() * ls.length)], arr = duelDiffIdx(k)[diff]; if (!arr.length) continue;
    const i = arr[Math.floor(Math.random() * arr.length)], q = duelLangPool(k)[i];
    const key = k + '|' + q.code + '|' + q.options.slice().sort().join('|'); if (used.has(key)) continue;
    used.add(key); return [k, i];
