  for (let g = 0; g < 50; g++) { const x = duelPickRefs(ls, 1)[0]; if (!x) break; const q = duelLangPool(x[0])[x[1]], key = x[0] + '|' + q.code + '|' + q.options.slice().sort().join('|'); if (!used.has(key)) { used.add(key); return x; } }
