      players.forEach((p) => { const [k, i] = duelPickByDiff(langs, d, used), L = duelLangPool(k)[i].options.length; u[p.uid] = { k, i, p: duelShuf(Array.from({ length: L }, (_, x) => x)).join('') }; });
