  return { lang: duelCfgLabel(cfg), kind, nn: n, nt: Math.max(1, ...players.map((p) => DUEL_TEAM_LABELS.indexOf(String(p.t)) + 1)), ver: duelVer(), qs, host: players[0].uid, pl, at: TS, t: cfg.t, nq: cfg.nq, lg: cfg.lg, rc: rc || '' };
