      const x = e0.u ? e0.u[u] : e0; if (!x) { ansBy[u].push(-1); return; }
      const qq = duelLangPool(x.k)[x.i], pm = String(x.p).split('').map(Number);
      ansBy[u].push(pm.indexOf(qq.answer));
