  const avg = (us) => us.length ? Math.round(us.reduce((s, u) => s + pl[u].r, 0) / us.length) : 0;
  const st = {}; oth.forEach((u) => { st[u] = { seen: { n: undefined, at: Date.now() }, ans: {}, ever: false, done: false, gone: false }; });
