  if (why === 'ff') dbPut('matches/' + o.mid + '/ff/' + o.uid, true).catch(() => {});
  const meta = { name: D.name, lang: D.lang, me: D.mine, bot: D.theirs, ff: why === 'ff' ? 1 : 0, on: 1, k: D.kind };
  D.over = D.ranked ? duelApply(D.n, res, D.my, D.op, meta) : duelNoRank(D.n, res, meta);
  D.over.forfeit = why === 'ff'; D.over.oppLeft = why === 'oppleft';
