    R.tm[me.uid] = DUEL_TEAM_LABELS.includes(R.prevTm[me.uid]) ? R.prevTm[me.uid] : 'A';
    await dbPut('rooms/' + R.code, { h: me.uid, n: me.name, r: duelRec(n).r, nn: n, nt: R.nt, t: TS, b: 0, tm: R.tm, cfg: R.cfg });
