  const P = { party: true, host: true, leader: me.uid, n, rk: !!rk, lang, fill, st: 'lobby', members: [{ u: me.uid, n: me.name, rr: {} }], stop: false, cnt: 0, seen: {}, pseen: {}, view: null }; DUQ = P;
