  const rows = ms.map((x, i) => '<div class="lobp">' + (i === 0 ? '👑 ' : '') + esc(x.n) + (x.u === me.uid ? ' (you)' : '') + '</div>').join('') + Array.from({ length: Math.max(0, n - ms.length) }, () => '<div class="lobp lobe">open slot</div>').join('');
