  const modeBox = (rank) => '<div class="dchips">' + [1, 2, 3, 4].map((k) => chip('data-dm', k, k === n, duelModeName(k))).join('') + (rank ? '<span style="width:12px"></span>' + chip('data-dr', 1, d.rk, '🏅 Ranked') + chip('data-dr', 0, !d.rk, 'Unranked') : '') + '</div>';
