  duelNote = ''; DP.sig1 = ''; DP.sig2 = ''; DP.sigI = '';
  bindTheme(); $('#back').addEventListener('click', () => go({ name: 'home' })); fbAccountBind();
  function saveName() { /* names are changed with the Change name button */ }
  $$('[data-tab]').forEach((b) => b.addEventListener('click', () => { saveName(); d.tab = b.dataset.tab; save(); renderDuel(); }));
  let cur = sel;
  const labels = () => {
    const dq = $('#dq'), dp = $('#dprac'), mk = $('#dmk');
    if (dq) dq.textContent = '🌐 Find ' + (d.rk ? 'a ranked' : 'an unranked') + ' ' + duelModeName(n) + ' match · ' + duelLangName(cur);
    if (dp) dp.textContent = '🤖 Practice vs computer · ' + duelLangName(cur) + ' (no rank change)';
    if (mk) mk.textContent = '👥 Create ' + duelModeName(n) + ' room · ' + duelLangName(cur);
  };
  labels();
