  $$('[data-dm]').forEach((b) => b.addEventListener('click', () => { saveName(); d.mode = +b.dataset.dm; save(); renderDuel(); }));
  $$('[data-dr]').forEach((b) => b.addEventListener('click', () => { saveName(); d.rk = b.dataset.dr === '1'; save(); renderDuel(); }));
